mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode,
c1.C_Name_History as svvContractorNameHistory, c1.C_Name as svvContractorName, c1.C_Abbreviation as svvContrAbbName, mn.* from Con_Sv_Verify mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on con.Con_Project_Id=pro.P_ID
left join SYS_Company c1 on mn.Svv_Contractor_Id=c1.C_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Svv_Create_Time desc
limit #{params.start},#{params.size}
